import {getAuth} from './auth.mjs';
try{const clerk=await getAuth();if(!clerk.user){location.replace('/login.html');}else{const owner=clerk.user.id;globalThis.nrVaultOwner=owner;clerk.addListener(({user})=>{if(user?.id!==owner){document.body.replaceChildren();location.replace('/login.html');}});await import('./app.mjs');document.documentElement.classList.remove('auth-loading');const signout=document.createElement('button');signout.textContent='Sign out';signout.className='language';signout.onclick=()=>clerk.signOut();document.querySelector('header').append(signout);}}catch{document.documentElement.classList.remove('auth-loading');document.body.replaceChildren();const box=document.createElement('main');box.textContent='Unable to check your sign-in. Please check your internet connection. ';const link=document.createElement('a');link.href='login.html';link.textContent='Return to login';box.append(link);document.body.append(box);}
